// Function executed by the new process
int child_entry(void *arg);

// Stack pointer (must point to the high address/top)
void *stack_top;

// Flags: Control resource sharing (CLONE_VM, CLONE_FILES)
// or namespace isolation (CLONE_NEWPID, CLONE_NEWNET)
#define CLONE_VM        0x00000100  // Share memory
#define CLONE_FILES     0x00000400  // Share file descriptors
#define CLONE_NEWPID    0x20000000  // New PID namespace

int flags = CLONE_VM | CLONE_SIGHAND; // Example: Thread-like behavior

// clone() is typically the C library wrapper around clone2()
pid_t child_pid = clone(
    child_entry,  // Function to run
    stack_top,    // Child stack pointer
    flags,        // Control mask
    NULL          // Argument passed to child_entry
);

// Parent returns child_pid (>0); Child returns 0; Failure returns -1.
// Note: Full clone signature may include pidfd/tls arguments.
